import Component from 'flarum/common/Component';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import * as api from '../api';
import { t } from '../util';
/** GIPHY search, through the forum's server (which holds the key). Its own lazy chunk. */
export default class GifPicker extends Component {
  q = '';
  results = [];
  loading = true;
  timer = 0;
  asked = 0;
  oninit(vnode) {
    super.oninit(vnode);
    this.search();
  }
  oncreate(vnode) {
    super.oncreate(vnode);
    this.element.querySelector('input')?.focus();
  }
  search() {
    const ask = ++this.asked;
    this.loading = true;
    api.searchGifs(this.q).then(results => {
      if (ask !== this.asked) return;
      this.results = results;
      this.loading = false;
      m.redraw();
    }, () => {
      this.loading = false;
      m.redraw();
    });
  }
  view() {
    return m("div", {
      className: "MomentGifPicker",
      onkeydown: e => e.key === 'Escape' && this.attrs.onclose()
    }, m("div", {
      className: "MomentGifPicker-head"
    }, m("input", {
      className: "FormControl",
      type: "search",
      placeholder: String(t('gifs.search')),
      "aria-label": String(t('gifs.search')),
      value: this.q,
      oninput: e => {
        this.q = e.target.value;
        clearTimeout(this.timer);
        this.timer = window.setTimeout(() => this.search(), 350);
      }
    }), m("button", {
      type: "button",
      className: "Button Button--icon Button--flat",
      "aria-label": String(t('gifs.close')),
      onclick: () => this.attrs.onclose()
    }, m("i", {
      className: "fas fa-xmark",
      "aria-hidden": "true"
    }))), m("div", {
      className: "MomentGifPicker-results"
    }, this.loading ? m(LoadingIndicator, {
      size: "small"
    }) : this.results.length ? this.results.map(gif => m("button", {
      type: "button",
      className: "MomentGifPicker-item",
      key: gif.id,
      "aria-label": gif.title || String(t('gifs.gif')),
      onclick: () => this.attrs.onpick(gif)
    }, m("img", {
      src: gif.preview,
      alt: "",
      loading: "lazy"
    }))) : m("p", {
      className: "MomentGifPicker-empty"
    }, t('gifs.none'))), m("div", {
      className: "MomentGifPicker-credit"
    }, t('gifs.credit')));
  }
}
flarum.reg.add('ernestdefoe-moments', 'forum/components/GifPicker', GifPicker);